import { useAuth } from '../context/AuthContext';

const statusColors = {
  draft: { bg: '#f3f4f6', text: '#6b7280' },
  published: { bg: '#dcfce7', text: '#16a34a' },
  cancelled: { bg: '#fee2e2', text: '#dc2626' },
  completed: { bg: '#e0e7ff', text: '#4f46e5' },
};

const priorityColors = {
  conference: '#8b5cf6', workshop: '#f59e0b', webinar: '#06b6d4',
  meetup: '#10b981', concert: '#ec4899', sports: '#f97316', other: '#6b7280',
};

export default function EventCard({ event, onEdit, onDelete }) {
  const { user } = useAuth();
  const canManage = user && (user.id === event.organiser?._id || user.role === 'admin');

  const fillPct = event.capacity > 0
    ? Math.min(100, Math.round((event.registeredCount / event.capacity) * 100))
    : 0;

  const statusStyle = statusColors[event.status] || statusColors.draft;

  return (
    <div style={{
      background: '#fff', borderRadius: 12, border: '1px solid #f3f4f6',
      padding: 20, display: 'flex', flexDirection: 'column', gap: 12,
      boxShadow: '0 1px 4px rgba(0,0,0,0.05)', transition: 'box-shadow 0.2s',
    }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 8 }}>
        <div>
          <span style={{
            fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 0.5,
            color: priorityColors[event.category] || '#6b7280',
          }}>
            {event.category}
          </span>
          <h3 style={{ margin: '4px 0 0', fontSize: 16, fontWeight: 600, color: '#111827', lineHeight: 1.3 }}>
            {event.title}
          </h3>
        </div>
        <span style={{
          padding: '3px 10px', borderRadius: 20, fontSize: 12, fontWeight: 600, whiteSpace: 'nowrap',
          background: statusStyle.bg, color: statusStyle.text,
        }}>
          {event.status}
        </span>
      </div>

      {/* Meta */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, fontSize: 13, color: '#6b7280' }}>
        <span>📅 {new Date(event.startDate).toLocaleDateString()}</span>
        <span>📍 {event.location}</span>
        {event.price > 0 && <span>💰 ₹{event.price}</span>}
      </div>

      {/* Capacity bar */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#6b7280', marginBottom: 4 }}>
          <span>Capacity</span>
          <span style={{ fontWeight: 600 }}>{event.registeredCount} / {event.capacity} ({fillPct}%)</span>
        </div>
        <div style={{ height: 6, borderRadius: 3, background: '#f3f4f6', overflow: 'hidden' }}>
          <div style={{
            height: '100%', borderRadius: 3, width: `${fillPct}%`,
            background: fillPct >= 90 ? '#ef4444' : fillPct >= 60 ? '#f59e0b' : '#6366f1',
            transition: 'width 0.4s ease',
          }} />
        </div>
      </div>

      {/* Actions */}
      {canManage && (
        <div style={{ display: 'flex', gap: 8, marginTop: 4 }}>
          <button onClick={() => onEdit(event)} style={{
            flex: 1, padding: '8px 0', borderRadius: 8, border: '1px solid #e5e7eb',
            background: '#fff', color: '#374151', fontWeight: 500, fontSize: 13, cursor: 'pointer',
          }}>
            ✏️ Edit
          </button>
          <button onClick={() => onDelete(event._id)} style={{
            flex: 1, padding: '8px 0', borderRadius: 8, border: '1px solid #fee2e2',
            background: '#fff5f5', color: '#ef4444', fontWeight: 500, fontSize: 13, cursor: 'pointer',
          }}>
            🗑️ Delete
          </button>
        </div>
      )}
    </div>
  );
}
